  // ------------------------------------------------------------------
  // Helpers
  // ------------------------------------------------------------------
  function makeResponse(data, contentType) {
    var body, ct;
    if (typeof data === 'string') {
      body = data;
      ct = contentType || 'text/plain; charset=utf-8';
    } else {
      body = JSON.stringify(data);
      ct = 'application/json; charset=utf-8';
    }
    return new Response(body, {
      status: 200,
      headers: { 'Content-Type': ct, 'Cache-Control': 'no-store' }
    });
  }

  function makeError(status, msg) {
    return new Response(JSON.stringify({ error: msg }), {
      status: status,
      headers: { 'Content-Type': 'application/json; charset=utf-8' }
    });
  }

  function parseQuery(urlStr) {
    var q = {};
    var idx = urlStr.indexOf('?');
    if (idx === -1) return q;
    var search = urlStr.slice(idx + 1);
    var pairs = search.split('&');
    for (var i = 0; i < pairs.length; i++) {
      var p = pairs[i].split('=');
      var k = decodeURIComponent(p[0]);
      var v = p[1] ? decodeURIComponent(p[1]) : '';
      q[k] = v;
    }
    return q;
  }

  // ------------------------------------------------------------------
  // Search query parser (mirrors src/searchQuery.js)
  // ------------------------------------------------------------------
  function parseSearchQuery(q) {
    var result = { textTerms: [], phrases: [], filters: {}, excludeFilters: {}, raw: q };
    var parts = q.match(/"[^"]+"|\S+/g) || [];
    for (var i = 0; i < parts.length; i++) {
      var part = parts[i];
      if (part.charAt(0) === '-') {
        var negKey = part.slice(1);
        var colonIdx = negKey.indexOf(':');
        if (colonIdx > 0) {
          var f = negKey.slice(0, colonIdx).toLowerCase();
          var v = negKey.slice(colonIdx + 1);
          result.excludeFilters[f] = v;
        } else {
          result.excludeFilters['text'] = negKey;
        }
        continue;
      }
      var ci = part.indexOf(':');
      if (ci > 0 && !part.startsWith('http') && !part.startsWith('"')) {
        var field = part.slice(0, ci).toLowerCase();
        var val = part.slice(ci + 1);
        // Only treat as field filter if field is a known field
        var knownFields = ['source', 'type', 'date', 'from', 'to', 'title', 'keyword', 'path', 'tasktype'];
        if (knownFields.indexOf(field) !== -1) {
          result.filters[field] = val;
          continue;
        }
      }
      // Strip quotes for phrases
      if (part.charAt(0) === '"' && part.charAt(part.length - 1) === '"') {
        result.phrases.push(part.slice(1, -1));
      } else {
        result.textTerms.push(part);
      }
    }
    return result;
  }

  function getAllSearchableText(t) {
    var parts = [];
    if (t.title) parts.push(t.title);
    if (t.userSummary) parts.push(t.userSummary);
    if (t.assistantSummary) parts.push(t.assistantSummary);
    if (t.taskType) parts.push(t.taskType);
    if (t.date) parts.push(t.date);
    if (t.source) parts.push(t.source);
    if (t.projectPath) parts.push(t.projectPath);
    if (Array.isArray(t.keywords)) parts.push(t.keywords.join(' '));
    return parts.join(' ');
  }

  function matchTask(t, parsed) {
    // Field filters
    if (parsed.filters.source) {
      if (String(t.source || '').toLowerCase() !== parsed.filters.source.toLowerCase()) return false;
    }
    if (parsed.filters.type || parsed.filters.tasktype) {
      var wantType = (parsed.filters.type || parsed.filters.tasktype).toLowerCase();
      if (String(t.taskType || 'unknown').toLowerCase() !== wantType) return false;
    }
    if (parsed.filters.date) {
      if (String(t.date || '') !== parsed.filters.date) return false;
    }
    if (parsed.filters.from) {
      if (!t.date || t.date === 'unknown' || t.date < parsed.filters.from) return false;
    }
    if (parsed.filters.to) {
      if (!t.date || t.date === 'unknown' || t.date > parsed.filters.to) return false;
    }
    if (parsed.filters.title) {
      if (!t.title || t.title.toLowerCase().indexOf(parsed.filters.title.toLowerCase()) === -1) return false;
    }
    if (parsed.filters.keyword) {
      if (!Array.isArray(t.keywords) || !t.keywords.some(function(k) { return k.toLowerCase().indexOf(parsed.filters.keyword.toLowerCase()) !== -1; })) return false;
    }
    if (parsed.filters.path) {
      if (!t.projectPath || t.projectPath.toLowerCase().indexOf(parsed.filters.path.toLowerCase()) === -1) return false;
    }
    // Text terms (must all match)
    if (parsed.textTerms.length > 0 || parsed.phrases.length > 0) {
      var allText = getAllSearchableText(t).toLowerCase();
      for (var i = 0; i < parsed.textTerms.length; i++) {
        if (allText.indexOf(parsed.textTerms[i].toLowerCase()) === -1) return false;
      }
      for (var j = 0; j < parsed.phrases.length; j++) {
        if (allText.indexOf(parsed.phrases[j].toLowerCase()) === -1) return false;
      }
    }
    // Exclude filters
    if (parsed.excludeFilters.text) {
      if (allText.indexOf(parsed.excludeFilters.text.toLowerCase()) !== -1) return false;
    }
    return true;
  }

  function snippetAround(text, idx, qLen, ctx) {
    ctx = ctx || 80;
    var start = Math.max(0, idx - ctx);
    var end = Math.min(text.length, idx + qLen + ctx);
    var pre = start > 0 ? '\u2026' : '';
    var post = end < text.length ? '\u2026' : '';
    var body = text.slice(start, end).replace(/\s+/g, ' ').trim();
    return pre + body + post;
  }

